def drive(me, enemy, arena):
    if me.inverted or me.on_side or me.airborne or not me.can_drive:
        return (0.0, 0.0)
    ex = enemy.x - me.x
    ey = enemy.y - me.y
    d = (ex * ex + ey * ey) ** 0.5
    if d < 0.05:
        return (1.0, 1.0)
    tx = -ey / d
    ty = ex / d
    r = d - 1.0
    vx = tx + (ex / d) * r * 1.2
    vy = ty + (ey / d) * r * 1.2
    rc = (me.x * me.x + me.y * me.y) ** 0.5
    if rc > 4.8:
        k = (rc - 4.8) * 1.5
        vx = vx - (me.x / rc) * k
        vy = vy - (me.y / rc) * k
    n = (vx * vx + vy * vy) ** 0.5
    if n < 0.001:
        return (1.0, 1.0)
    vx = vx / n
    vy = vy / n
    b = bearing_to(me.x + vx * 5.0, me.y + vy * 5.0)
    s = b / 40.0
    if s > 1.0:
        s = 1.0
    if s < -1.0:
        s = -1.0
    return (1.0 - s, 1.0 + s)


