def drive(me, enemy, arena):
    # Simple proportional steering towards the enemy
    bearing = bearing_to(enemy.x, enemy.y)  # degrees, positive to our left
    dist = distance_to(enemy.x, enemy.y)

    # Reduce speed when very close to avoid collisions
    if dist < 1.0:
        base = 0.5
    else:
        base = 1.0

    # Turn rate: if bearing is to the left, slow left wheel; if to the right, slow right wheel
    if bearing > 5:
        left = base * 0.6
        right = base
    elif bearing < -5:
        left = base
        right = base * 0.6
    else:
        left = right = base

    return (left, right)


def weapons(me, enemy, arena):
    cmds = []

    # Keep the front spinner at max rpm
    front = me.weapons.get("front")
    if front and front["type"] == "spinner":
        cmds.append(spin("front", front["max_rpm"]))

    # Clamp logic: try to grab when close and open, release after holding for a short time
    back = me.weapons.get("back")
    if back and back["type"] == "clamp":
        # Initialize memory for hold timer if not present
        if "clamp_release_time" not in me.memory:
            me.memory["clamp_release_time"] = 0.0

        dist = distance_to(enemy.x, enemy.y)
        state = back.get("state", "open")

        if state == "open" and dist < 0.6:
            # Grab and set release time 2 seconds later
            cmds.append(grab("back"))
            me.memory["clamp_release_time"] = arena.time + 2.0
        elif state == "holding" and arena.time >= me.memory.get("clamp_release_time", 0.0):
            cmds.append(release("back"))

    return cmds
